import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"61、【中孚】 兑下巽上","description":"周易口诀义 - 61、【中孚】 兑下巽上","frontmatter":{"title":"61、【中孚】 兑下巽上","description":"周易口诀义 - 61、【中孚】 兑下巽上"},"headers":[],"relativePath":"zh/classics/koujueyi/063.md","filePath":"zh/classics/koujueyi/063.md"}'),r={name:"zh/classics/koujueyi/063.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_61、【中孚】-兑下巽上" tabindex="-1">61、【中孚】 兑下巽上 <a class="header-anchor" href="#_61、【中孚】-兑下巽上" aria-label="Permalink to “61、【中孚】 兑下巽上”">​</a></h1><p>彖曰：中孚，柔在内而刚得中。说而巽，孚乃化邦也。「豚鱼吉」，信及豚鱼也。「利涉大川」，乘木舟虚也。中孚以「利贞」，乃应乎天也。</p><p>象曰：泽上有风，中孚。君子以议狱缓死。</p><p>初九：虞吉，有他不燕。象曰：「初九虞吉」，志未变也。</p><p>九二：鸣鹤在阴，其子和之。我有好爵，吾与尔靡之。</p><p>象曰：「其子和之」，中心愿也。</p><p>六三：得敌，或鼓或罢，或泣或歌。</p><p>象曰：「或鼓或罢」，位不当也。</p><p>六四：月几望，马匹亡，无咎。</p><p>象曰：「马匹亡」，绝类上也。</p><p>九五：有孚挛如，无咎。</p><p>象曰：「有孚挛如」，位正当也。</p><p>上九：翰音登于天，贞凶。</p><p>象曰：「翰音登于天」，何可长也。</p><p>无（四库全书标明，摘录时缺豫、随、无妄、大壮、晋、睽、蹇、解、中孚八卦）</p>',15)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
